import os
import io
import tokenize

root = os.getcwd()
results = []

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d != '.git']
    for fn in filenames:
        if not fn.endswith('.py'):
            continue
        full = os.path.join(dirpath, fn)
        rel = os.path.relpath(full, root).replace(os.sep, '/')
        try:
            with tokenize.open(full) as f:
                src = f.read()
            for tok in tokenize.generate_tokens(io.StringIO(src).readline):
                if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                    results.append((rel, tok.start[0]))
        except (tokenize.TokenError, SyntaxError, OSError, UnicodeDecodeError):
            pass

results.sort()
with open(os.path.join(root, 'todos.txt'), 'w') as out:
    for rel, line in results:
        out.write(rel + ':' + str(line) + '\n')

print(len(results))
